mapper.select:
select r.id as regionId, r.region_name, r.region_type, r.creator, r.modifier, r.create_time, r.update_time, r.region_json, count(distinct t.id) as unionTemplateCount from vm_radar_alarm_region r left join vm_radar_alarm_template_region_rel t on t.region_id = r.id and t.tenant_id = r.tenant_id and t.industry_code = r.industry_code where r.delete_flag = '0'
and r.id in
#{item}
and r.region_name like CONCAT('%', #{dto.regionName}, '%')
and r.region_type = #{dto.regionType}
and r.creator like CONCAT('%', #{dto.creator}, '%')
${dto.dataScope}
and r.modifier like CONCAT('%', #{dto.modifier}, '%')
and r.create_time >= #{dto.createTimeBegin}
and r.create_time <= #{dto.createTimeEnd}
and r.update_time >= #{dto.updateTimeBegin}
and r.update_time <= #{dto.updateTimeEnd}
group by r.id
having unionTemplateCount > 0
having unionTemplateCount = 0
order by r.create_time
asc
desc
order by r.update_time
asc
desc
order by r.create_time desc

select id regionId, region_name, region_type,region_json from vm_radar_alarm_region where tenant_id = #{tenantId} and industry_code = #{industryCode} and delete_flag = 0
and region_type in
#{item}

select region_id
from vm_radar_alarm_template_region_rel
where template_id = #{templateId}

select count(*)
from vm_radar_alarm_template_region_rel
where region_id = #{regionId}

mapper.update:
update vm_radar_alarm_region
set delete_flag = 1, modifier = #{userName}, update_time = now()
where id = #{regionId}

mapper.select:
select id, region_name regionName, region_type regionType, region_json regionJsonStr
from vm_radar_alarm_region
where id = #{regionId}
